def clearSelected():
	"""
	If an alarm is selected in the alarm list and the user
		clicks on an item in the tag tree, then clear out
		the selection.
	"""
	if self.parent.parent.getChild("Alarms").getChild("Alarm Container").getChild("Alarm List").props.selection.selectedRow != None:
		system.perspective.sendMessage("updateSelectedRow", payload = {'row':None}, scope = "page")
		self.parent.parent.getChild("Alarms").getChild("Alarm Container").getChild("Alarm List").props.selection.selectedRow = None

# if the selectedRow in the Alarm List is not equal to None when the user 
# clicks on an item in the tree, then set it to None
clearSelected()

# updating the items displayed in the tree depending on the type of item
# that was clicked on and whether an item was closed/opened (if the item
# is a folder or UDT instance)

currentLevel = {}

self.props.interactable = False

for item in event.itemPath:
	if currentLevel == {}:
		currentLevel = self.props.items[item]
	else:
		currentLevel = currentLevel["items"][item]

itemPath = "/".join(map(str,event.itemPath))

if currentLevel["expanded"] and currentLevel["data"]["hasChildren"]:
	currentLevel["items"] = [{"label":"Fake Item","expanded":False,"data":{},"items":[]}]
else:
	tags = []

	if currentLevel["data"].has_key("folder"):
		baseTagFolder = currentLevel["data"]["folder"]
		if currentLevel["data"].has_key("folder"):
			# folder or udt instance expanded, call browse to get the new items
			results = system.tag.browse(baseTagFolder).getResults()

			for result in results:
				if result["name"] != "_types_":
					if str(result["tagType"]) in ["Folder", "UdtInstance"]:
						tag = {'label': result["name"], 'expanded': False, 'data': {'folder':result["fullPath"], 'hasChildren':result["hasChildren"]}, "items":[]}

						# if the folder/UDT instance has children, add a fake item to make it appear that the tree item has children
						if result["hasChildren"]:
							tag['items'].append({"label":"Fake Item","expanded":False,"data":{},"items":[]})

						tags.append(tag)
					else:
						tags.append({'label': result["name"], 'data': {'tag': result["fullPath"], 'hasChildren':result["hasChildren"]}, 'items': [], 'expanded': False})

			currentLevel["items"] =  tags

# update selection of tree
self.props.selection = [itemPath]
self.props.selectionData = [{"itemPath":itemPath,"value":currentLevel["data"]}]

# if item was expanded when it was clicked, close it; otherwise, expand it
currentLevel["expanded"] = not currentLevel["expanded"]

if 'tag' in currentLevel["data"].keys():
	tagPath = currentLevel["data"]["tag"]
else:
	tagPath = ''

# send message to updateTagPath to update the selected tag path along with the tag tree selection info
system.perspective.sendMessage('updateTagPath', payload = {'path':tagPath, 'selections':(itemPath,{"itemPath":itemPath,"value":currentLevel["data"]})}, scope = "page")

# the items of the tag tree change when opening/closing folders/UDT instances, so in order to sync
# the state of the tag tree between the large view and the small view, call updateItems and pass
# in the items currently being displayed in the tag tree
system.perspective.sendMessage('updateItems',payload={'items':self.props.items},scope='page')

