# columns of the alarm list: Name, Mode, Priority

# tag path is empty, set local selectedRow to None and send a message to updateSelectedRow to
# set the selectedRow custom property on alarm-configurator view to None; return empty list
if 'path' not in value.keys():
	system.perspective.sendMessage("updateSelectedRow", payload = {'row':None}, scope = "page")
	self.props.selection.selectedRow = None
	return []
else:
	logger = system.util.getLogger('configurator.lg.alarmlist')
	logger.debug('updating alarms in alarm list; tagpath= ' + value['path'])

	# tag path not empty, checking to see if tag has alarms; if it does,
	# grab the alarms list, and save the alarm names in the 'names' list
	if 'alarms' in value.keys():
		alarms = value['alarms']
		names = []
		for alarm in alarms:
			names.append(alarm['name'])
		logger.debug('alarm names= ' + str(names) + '; tagpath= ' + value['path'])
	else:
		alarms = []
		logger.debug('no alarms; tagpath= ' + value['path'])

	udtDefAlarms = self.view.params.udtDefAlarms
	udtDefAlarmNames = []

	# if the tag has UDT definition alarms, then take the names of
	# the UDT defined alarms and add them to a list
	for udtDefAlarm in udtDefAlarms:
		udtDefAlarmNames.append(udtDefAlarm['name'])

	alarmListData = []

	for alarm in alarms:
		# check 'enabled' property of alarm to determine font color of the row (grey for disabled)
		if 'enabled' in alarm.keys():
			if str(type(alarm['enabled'])) == "<type 'com.inductiveautomation.perspective.gateway.script.DotReferenceJythonMap'>":
				enabled = str(alarm['enabled']['value'])
			else:
				enabled = str(alarm['enabled'])
		else:	
			enabled = 'True'

		if enabled == 'True':
			enabledColor = '--neutral-100'
		else:
			enabledColor = '--neutral-50'

		# if mode is not in the keys of the alarm object, then it is set to the default 'Equal'
		if 'mode' in alarm.keys():
			mode = str(alarm['mode'])
			if mode == '':
				mode = 'Equal'
		else:
			mode = 'Equal'

		# if priority is not in the keys of the alarm object, then it is set to the default 'Low'	
		if 'priority' in alarm.keys():
			if str(type(alarm['priority'])) == "<type 'com.inductiveautomation.perspective.gateway.script.DotReferenceJythonMap'>":
				priority = str(alarm['priority']['bindType'])
			else:
				priority = str(alarm['priority'])
		else:	
			priority = 'Low'

		# if this alarm is a UDT alarm, then check to see if this alarm has the same exact properties
		# as the alarm in the UDT definition, and if it does, display a grey circle, otherwise display
		# a green circle
		if alarm['name'] in udtDefAlarmNames:
			index = udtDefAlarmNames.index(alarm['name'])
			udtAlarm = dict(udtDefAlarms[index].items())

			if set(alarm.keys()) == set(udtAlarm.keys()) and set(alarm.values()) == set(udtAlarm.values()):
				color = '--neutral-40'
			else:
				color = '--indicator'
			udt = True
		else:
			color = '--neutral-100'
			udt = False

		alarmListData.append({'enabled':enabled,'fontSize':14,'udt':udt,'color':color,'name': alarm['name'],'mode':{'value':mode,'style':{"classes": "","backgroundColor": '--neutral-10',"color":enabledColor,"fontFamily": "Helvetica"},'align':'center','justify':'center'},'priority':{'value':priority,'style':{"classes": "","backgroundColor":'--neutral-10',"color": enabledColor,"fontFamily": "Helvetica"},'align':'center','justify':'center'}})

	return alarmListData

# if neither add alarm or delete alarm buttons are visible, then do not show this container
if value['addIconDisplay'] == False and value['deleteIconDisplay'] == False:
	return False
else:
	return True

# when the tagConfig or selectedRow param changes, this determines either which
# alarm object should be passed to the property editor, or if an empty object
# should be passed (because no alarm is selected)

selectedRow = value['selectedRow']
config = value['tagConfig']

if selectedRow == None:
	return {}
else:
	# selectedRow not equal to None, find the alarm in the tagConfig alarm list
	# and return the object
	if 'alarms' in config.keys():
		logger = system.util.getLogger('configurator.lg.properties')
		logger.debug('alarm param populated; alarm= ' + str(config['alarms'][selectedRow]))		

		return config['alarms'][selectedRow]
	else:
		return {}

# in order to prevent duplicate alarm names, pass in the names for all the
# alarms that this tag has; then, when user changes alarm name, can check
# to see if it is a duplicate or not

if len(value.keys()) > 0:
	alarmNames = []
	if 'alarms' in value.keys():
		for alarm in value['alarms']:
			alarmNames.append(alarm['name'])
	return alarmNames
else:
	return []

# check to see if this alarm is a UDT alarm, and if it is, get the object
# that represents the alarm in the UDT definition and pass it to the
# property editor; if this alarm is not a UDT alarm, then return an empty
# object

logger = system.util.getLogger('configurator.lg.properties')

if 'name' in value.keys():
	currAlarmName = value['name']
else:
	currAlarmName = 'Alarm'

for alarm in self.view.params.udtDefAlarms:
	if currAlarmName == alarm['name']:
		logger.debug('alarm is a UDT alarm; alarm name= ' + str(currAlarmName))
		return alarm

logger.debug('alarm is not a UDT alarm; alarm name= ' + str(currAlarmName))
return {}

# return the name of the alarm; if 'name' is not in alarm object's keys,
# then name is set to default 'Alarm'

if 'name' in value.keys():
	return value['name']
else:
	return 'Alarm'
